import math
import re
import numpy as np
from wordfreq import word_frequency
from difflib import SequenceMatcher

_W = re.compile(r"[a-zA-Z']+")
STOP = set(("a an the and or but if then else of to in on at by for with from as is are was were "
    "be been being it its this that these those i you he she we they me him her us them my your "
    "his their our not no so do does did have has had will would can could should may might must "
    "about into over under out up down off than too very just also").split())

def _toks(s):
    return [t for t in _W.findall((s or "").lower())]

def _content(s):
    return [t for t in _toks(s) if t not in STOP and len(t) > 1]

def _mtld_forward_backward(tokens, min_ttr=0.72):
    if not tokens or len(tokens) < 2:
        return 0.0, 0.0, 0.0
    types_seen = set()
    factor_count = 0.0
    for i, token in enumerate(tokens):
        types_seen.add(token)
        ttr = len(types_seen) / (i + 1)
        if ttr <= min_ttr:
            factor_count += 1
            types_seen = set()
    if types_seen:
        factor_count += len(types_seen) / len(tokens)
    if factor_count <= 0:
        mtld_forward = 0.0
    else:
        mtld_forward = len(tokens) / factor_count
    tokens_rev = list(reversed(tokens))
    types_seen = set()
    factor_count = 0.0
    for i, token in enumerate(tokens_rev):
        types_seen.add(token)
        ttr = len(types_seen) / (i + 1)
        if ttr <= min_ttr:
            factor_count += 1
            types_seen = set()
    if types_seen:
        factor_count += len(types_seen) / len(tokens_rev)
    if factor_count <= 0:
        mtld_backward = 0.0
    else:
        mtld_backward = len(tokens_rev) / factor_count
    mtld_avg = (mtld_forward + mtld_backward) / 2.0
    return mtld_forward, mtld_backward, mtld_avg

def mtld_diversity_anchor_relative(text, anchor):
    if not (text and anchor):
        return 0.5
    anchor_toks = _content(anchor)
    text_toks = _content(text)
    if not text_toks or not anchor_toks:
        return 0.5
    matcher = SequenceMatcher(None, anchor_toks, text_toks)
    changed_toks = []
    for op, a_start, a_end, b_start, b_end in matcher.get_opcodes():
        if op in ("replace", "insert"):
            changed_toks.extend(text_toks[b_start:b_end])
    if not changed_toks:
        changed_toks = text_toks
    _, _, changed_mtld = _mtld_forward_backward(changed_toks)
    _, _, anchor_mtld = _mtld_forward_backward(anchor_toks)
    if anchor_mtld < 5:
        return 0.5
    ratio = changed_mtld / anchor_mtld if anchor_mtld > 0 else 1.0
    score = 0.5 + 0.5 * ((ratio - 1.0) / (ratio + 1.0))
    return max(0.0, min(1.0, score))

METRICS = {"mtld_diversity_anchor_relative": mtld_diversity_anchor_relative}

import math
import re
import numpy as np
from wordfreq import word_frequency
from scipy import linalg
from difflib import SequenceMatcher

_W = re.compile(r"[a-zA-Z']+")
STOP = set(("a an the and or but if then else of to in on at by for with from as is are was were "
    "be been being it its this that these those i you he she we they me him her us them my your "
    "his their our not no so do does did have has had will would can could should may might must "
    "about into over under out up down off than too very just also").split())

def _toks(s):
    return [t for t in _W.findall((s or "").lower())]

def _content(s):
    return [t for t in _toks(s) if t not in STOP and len(t) > 1]

def _word_surprisal(word):
    p = word_frequency(word, "en")
    if p > 0:
        return -math.log2(p)
    return 24.0

def _residualized_novelty(tokens):
    if not tokens:
        return 0.0
    surprisals = []
    log_freqs = []
    for tok in tokens:
        surp = _word_surprisal(tok)
        freq = word_frequency(tok, "en")
        if freq > 0 and surp < 30:
            surprisals.append(surp)
            log_freqs.append(math.log10(freq + 1e-10))
    if len(surprisals) < 3:
        return 0.0
    X = np.array(log_freqs, dtype=float).reshape(-1, 1)
    y = np.array(surprisals, dtype=float)
    try:
        result = linalg.lstsq(np.column_stack([np.ones(len(X)), X]), y)
        residuals = y - (result[0][0] + result[0][1] * X.flatten())
        return float(np.mean(residuals))
    except:
        return 0.0

def word_frequency_confound_residuals(text, anchor):
    text_toks = _content(text)
    anchor_toks = _content(anchor)
    if not text_toks or not anchor_toks:
        return 0.5
    matcher = SequenceMatcher(None, anchor_toks, text_toks)
    changed_toks = []
    for op, a_start, a_end, b_start, b_end in matcher.get_opcodes():
        if op in ("replace", "insert"):
            changed_toks.extend(text_toks[b_start:b_end])
    if not changed_toks:
        changed_toks = text_toks
    residual_mean = _residualized_novelty(changed_toks)
    score = 0.5 + 0.2 * residual_mean
    return max(0.0, min(1.0, score))

METRICS = {"word_frequency_confound_residuals": word_frequency_confound_residuals}

import math
import re
import statistics
from wordfreq import word_frequency
from difflib import SequenceMatcher

_W = re.compile(r"[a-zA-Z']+")
STOP = set(("a an the and or but if then else of to in on at by for with from as is are was were "
    "be been being it its this that these those i you he she we they me him her us them my your "
    "his their our not no so do does did have has had will would can could should may might must "
    "about into over under out up down off than too very just also").split())

def _toks(s):
    return [t for t in _W.findall((s or "").lower())]

def _content(s):
    return [t for t in _toks(s) if t not in STOP and len(t) > 1]

def _bigram_transition_surprisal(tokens):
    if len(tokens) < 2:
        return 0.0
    bigram_surprisals = []
    for i in range(len(tokens) - 1):
        w1, w2 = tokens[i], tokens[i + 1]
        p1 = word_frequency(w1, "en")
        p2 = word_frequency(w2, "en")
        if p1 > 0 and p2 > 0:
            joint_independent = p1 * p2
            surp = -math.log2(joint_independent + 1e-30)
            bigram_surprisals.append(surp)
    if not bigram_surprisals:
        return 0.0
    return float(statistics.mean(bigram_surprisals))

def bigram_transition_improbability(text, anchor):
    text_toks = _content(text)
    anchor_toks = _content(anchor)
    if not text_toks or not anchor_toks:
        return 0.5
    matcher = SequenceMatcher(None, anchor_toks, text_toks)
    changed_toks = []
    for op, a_start, a_end, b_start, b_end in matcher.get_opcodes():
        if op in ("replace", "insert"):
            changed_toks.extend(text_toks[b_start:b_end])
    if not changed_toks or len(changed_toks) < 2:
        changed_toks = text_toks
    mean_bigram_surp = _bigram_transition_surprisal(changed_toks)
    if mean_bigram_surp < 0:
        score = 0.5
    else:
        score = math.exp(-((mean_bigram_surp - 22.0) ** 2) / (2 * 6.0 ** 2))
    return max(0.0, min(1.0, score))

METRICS = {"bigram_transition_improbability": bigram_transition_improbability}
